def factor(x):
    d=2
    while d*d<=x:
        if x%d==0:
            c=0
            while x%d==0:
                x//=d; c+=1
            yield d,c
        d+=1
    if x>1:
        yield x,1

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    aa=data[1:]
    seq={}
    for i,x in enumerate(aa):
        for p,e in factor(x):
            if p not in seq:
                seq[p]=[0]*(n-1)
            seq[p][i]=e
    ans=1
    for p, es in seq.items():
        total=sum(es)
        maxpow=max(total, 9*n)
        powers=[1]*(maxpow+1)
        for i in range(1,maxpow+1):
            powers[i]=powers[i-1]*p%MOD
        dp=[0]*(total+1)
        dp[0]=1
        maxh=0
        t=1
        for a in es:
            nd=[0]*(total+1)
            if a==0:
                for h in range(maxh+1):
                    if dp[h]:
                        nd[h]=dp[h]*powers[h]%MOD
            else:
                for h in range(maxh+1):
                    v=dp[h]
                    if not v:
                        continue
                    z=h+a
                    nd[z]=(nd[z]+v*powers[z])%MOD
                    z=h-a
                    if z>=0:
                        nd[z]=(nd[z]+v*powers[z])%MOD
                    else:
                        nd[0]=(nd[0]+v*powers[-z*t])%MOD
                maxh=min(total,maxh+a)
            dp=nd
            t+=1
        ans=ans*sum(dp)%MOD
