from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = sorted((a, b))
            at[y].append((x, i))

        largest = second = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for x, pair_id in at[right]:
                if x >= largest:
                    second = largest
                    largest = x
                    largest_id = pair_id
                elif x > second:
                    second = x

            total += right - largest
            if largest_id != -1:
                gains[largest_id] += largest - second

        return total + max(gains)

