from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            x,y=sorted((a,b))
            at[y].append((x,i))
        first=second=0
        first_id=-1
        gain=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for x,i in at[r]:
                if x>=first:
                    second=first
                    first,first_id=x,i
                elif x>second:
                    second=x
            total += r-first
            if first_id>=0:
                gain[first_id] += first-second
        return total+max(gain)

