import sys
input = sys.stdin.buffer.readline

N, M, Q = map(int, input().split())
edges = []
for _ in range(M):
    a, b, c = map(int, input().split())
    edges.append((a - 1, b - 1, c))

queries = []
closed = [False] * M
for _ in range(Q):
    values = list(map(int, input().split()))
    if values[0] == 1:
        idx = values[1] - 1
        closed[idx] = True
        queries.append((1, idx))
    else:
        queries.append((2, values[1] - 1, values[2] - 1))

INF = 10**30
dist = [[INF] * N for _ in range(N)]
for i in range(N):
    dist[i][i] = 0
for i, (a, b, c) in enumerate(edges):
    if not closed[i]:
        dist[a][b] = dist[b][a] = c

# APSP in the graph after all closures.
for k in range(N):
    row_k = dist[k]
    for i in range(N):
        dik = dist[i][k]
        if dik == INF:
            continue
        row_i = dist[i]
        for j in range(N):
            candidate = dik + row_k[j]
            if candidate < row_i[j]:
                row_i[j] = candidate

answers = []
for query in reversed(queries):
    if query[0] == 2:
        _, x, y = query
        value = dist[x][y]
        answers.append(str(value if value < INF else -1))
    else:
        _, idx = query
        a, b, weight = edges[idx]
        # Add this road to the graph. Any new shortest path uses it at most once.
        to_a = [dist[i][a] for i in range(N)]
        to_b = [dist[i][b] for i in range(N)]
        for i in range(N):
            row = dist[i]
            via_a = to_a[i] + weight
            via_b = to_b[i] + weight
            for j in range(N):
                candidate = min(via_a + to_b[j], via_b + to_a[j])
                if candidate < row[j]:
                    row[j] = candidate

print('\n'.join(reversed(answers)))

