import sys
sys.setrecursionlimit(1_000_000)
data=list(map(int,sys.stdin.buffer.read().split()))
N=data[0]
A=data[1:]

pref=[0]*(N+1)
seen=set()
for i,x in enumerate(A,1):
    seen.add(x)
    pref[i]=len(seen)

suf=[0]*(N+1)
seen=set()
for i in range(N-1,-1,-1):
    seen.add(A[i])
    suf[i]=len(seen)

mx=[0]*(4*(N+1))
lazy=[0]*(4*(N+1))
def build(v,l,r):
    if l==r:
        mx[v]=pref[l]
    else:
        m=(l+r)//2
        build(v*2,l,m)
        build(v*2+1,m+1,r)
        mx[v]=max(mx[v*2],mx[v*2+1])
def push(v):
    z=lazy[v]
    if z:
        c=v*2
        mx[c]+=z; lazy[c]+=z
        mx[c+1]+=z; lazy[c+1]+=z
        lazy[v]=0
def add(v,l,r,ql,qr):
    if ql<=l and r<=qr:
        mx[v]+=1
        lazy[v]+=1
        return
    push(v)
    m=(l+r)//2
    if ql<=m: add(v*2,l,m,ql,qr)
    if qr>m: add(v*2+1,m+1,r,ql,qr)
    mx[v]=max(mx[v*2],mx[v*2+1])
def query(v,l,r,qr):
    if r<=qr: return mx[v]
    push(v)
    m=(l+r)//2
    if qr<=m:
        return query(v*2,l,m,qr)
    return max(mx[v*2],query(v*2+1,m+1,r,qr))

build(1,1,N-2)
last={A[0]:0}
answer=0
for j in range(1,N-1):
    prev=last.get(A[j],-1)
    last[A[j]]=j
    left=max(1,prev+1)
    if left<=j:
        add(1,1,N-2,left,j)
    answer=max(answer,query(1,1,N-2,j)+suf[j+1])
print(answer)

