class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = depth[x.bit_count()] + 1

        valid = [False] * (n + 1)
        for ones in range(1, n + 1):
            # A number with this popcount takes one operation to reach ones,
            # then depth[ones] further operations to reach 1.
            valid[ones] = depth[ones] + 1 <= k

        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                for total_ones in range(1, n + 1):
                    if valid[total_ones]:
                        need = total_ones - prefix_ones
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                prefix_ones += 1
        return ans % MOD

