from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise
        size = n * m
        used = [[0] * size for _ in range(4)]

        # Longest valid continuation when the turn has already been used.
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            arr = used[d]
            for r in rows:
                base = r * m
                for c in cols:
                    v = grid[r][c]
                    if v not in (0, 2):
                        continue
                    nr, nc = r + dr, c + dc
                    length = 1
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        length += arr[nr * m + nc]
                    arr[base + c] = length

        answer = 1 if any(v == 1 for row in grid for v in row) else 0
        # With the turn still available, it can either continue straight or turn clockwise.
        for d, (dr, dc) in enumerate(dirs):
            turn_d = (d + 1) % 4
            tdr, tdc = dirs[turn_d]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            free = [0] * size
            for r in rows:
                base = r * m
                for c in cols:
                    v = grid[r][c]
                    if v not in (0, 2):
                        continue
                    nr, nc = r + dr, c + dc
                    best = 0
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        ni = nr * m + nc
                        best = free[ni]
                        tr, tc = r + tdr, c + tdc
                        if 0 <= tr < n and 0 <= tc < m and grid[tr][tc] == 2 - v:
                            best = max(best, used[turn_d][tr * m + tc])
                    free[base + c] = 1 + best

            # Every segment starts at 1; its first following cell must be 2.
            for r in range(n):
                for c in range(m):
                    if grid[r][c] != 1:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        answer = max(answer, 1 + free[nr * m + nc])
        return answer

