from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        unused = set(range(1, n + 1))
        result = []
        previous_parity = None

        while unused:
            for value in sorted(unused):
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                remaining = unused - {value}
                odds = sum(x % 2 for x in remaining)
                evens = len(remaining) - odds

                # The remaining sequence must start with the opposite parity.
                first_needed = 1 - parity
                odd_slots = (len(remaining) + (1 if first_needed == 1 else 0)) // 2
                even_slots = len(remaining) - odd_slots

                count = factorial(odds) * factorial(evens) if (odds, evens) == (odd_slots, even_slots) else 0

                if k > count:
                    k -= count
                else:
                    result.append(value)
                    unused.remove(value)
                    previous_parity = parity
                    break
            else:
                return []

        return result

