class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if j != i:
                c += powers[j]
            coeff.append(c % k)

        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Only residue 0 is achievable with no positions left.

        for i in range(m - 1, -1, -1):
            base = suffix[i + 1]
            c = coeff[i]
            reachable = 0
            for d in range(10):
                shift = (c * d) % k
                if shift == 0:
                    rotated = base
                else:
                    rotated = ((base << shift) | (base >> (k - shift))) & full
                reachable |= rotated
            suffix[i] = reachable

        digits = []
        remainder = 0
        for i, c in enumerate(coeff):
            lower = 1 if i == 0 else 0
            for d in range(9, lower - 1, -1):
                new_remainder = (remainder + c * d) % k
                needed = (-new_remainder) % k
                if (suffix[i + 1] >> needed) & 1:
                    digits.append(str(d))
                    remainder = new_remainder
                    break

        left = ''.join(digits)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

