from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            nxt[i] = st[-1] if st else n
            st.append(i)

        # Binary lifting over successive prefix-maximum positions.
        levels = n.bit_length()
        dest = [nxt]
        agg = [[(nxt[i] - i) * nums[i] for i in range(n)]]
        for _ in range(1, levels):
            prev_d, prev_a = dest[-1], agg[-1]
            drow = [n] * n
            arow = [0] * n
            for i in range(n):
                mid = prev_d[i]
                if mid < n:
                    drow[i] = prev_d[mid]
                    arow[i] = prev_a[i] + prev_a[mid]
                else:
                    drow[i] = n
                    arow[i] = prev_a[i]
            dest.append(drow)
            agg.append(arow)

