        b_part = p[i + 1:j]
        c_part = p[j + 1:]
        n = len(s)

        def occurrences(pattern):
            if not pattern:
                return list(range(n + 1))

            m = len(pattern)
            prefix = [0] * m
            k = 0
            for q in range(1, m):
                while k and pattern[q] != pattern[k]:
                    k = prefix[k - 1]
                if pattern[q] == pattern[k]:
                    k += 1
                prefix[q] = k

            result = []
            k = 0
            for q, ch in enumerate(s):
                while k and ch != pattern[k]:
                    k = prefix[k - 1]
                if ch == pattern[k]:
                    k += 1
                if k == m:
                    result.append(q - m + 1)
                    k = prefix[k - 1]
            return result

        starts_a = occurrences(a_part)
        starts_b = occurrences(b_part)
        starts_c = occurrences(c_part)

        best = n + 1
        for start_a in starts_a:
            idx_b = bisect_left(starts_b, start_a + len(a_part))
            if idx_b == len(starts_b):
