def solve_case(a, b):
    src = [i for i, c in enumerate(a) if c == '1']
    dst = [i for i, c in enumerate(b) if c == '1']

    if len(src) < len(dst):
        return -1

    # For a given distance limit, check whether the source positions can
    # cover every destination in order, with every source assigned to one.
    def possible(limit):
        j = 0
        for x in src:
