class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Produce the postorder string iteratively, while recording each
        # subtree's half-open interval in that string.
        text_parts = []
        start = [0] * n
        end = [0] * n
        stack = [(0, False)]
        while stack:
            u, exiting = stack.pop()
            if not exiting:
                start[u] = len(text_parts)
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))
            else:
                text_parts.append(s[u])
                end[u] = len(text_parts)

        text = ''.join(text_parts)

        # Manacher's algorithm: d1[i] is the odd radius, d2[i] the even radius.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = []
        for u in range(n):
            length = end[u] - start[u]
            center = start[u] + length // 2
            if length % 2:
                answer.append(d1[center] >= length // 2 + 1)
            else:
                answer.append(d2[center] >= length // 2)
        return answer

