class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For a subarray [l, r), its length is divisible by k exactly
        # when l and r have the same remainder modulo k.
        min_prefix = {0: 0}
        prefix = 0
        best = None

        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k

            if remainder in min_prefix:
                best_sum = prefix - min_prefix[remainder]
                if best is None or best_sum > best:
                    best = best_sum
                if prefix < min_prefix[remainder]:
                    min_prefix[remainder] = prefix
            else:
                min_prefix[remainder] = prefix

        return best

