class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        # Every intermediate number has the same digit count as n.
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        is_prime = [True] * (high + 1)
        if high >= 0:
            is_prime[0] = False
        if high >= 1:
            is_prime[1] = False
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, high + 1, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        # Place values corresponding to each digit, from left to right.
        places = [10 ** i for i in range(digits - 1, -1, -1)]
        dist = {n: n}  # The starting number is included in the cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt <= high and not is_prime[nxt]:
