from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        answer = 0

        for i in range(1, n - 1):
            # First subarray is a prefix of the second.
            first_ok = 2 * i <= n and nums[:i] == nums[i:2 * i]
            if first_ok:
                answer += max(0, n - 2 * i)

            # For every possible second-subarray length, compute its LCP
            # with the third subarray using the Z algorithm on nums[i:].
            m = n - i
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])
                while (i + z[k] < n and i + k + z[k] < n
                       and nums[i + z[k]] == nums[i + k + z[k]]):
                    z[k] += 1
                if k + z[k] - 1 > right:
                    left, right = k, k + z[k] - 1

            # Third subarray must be at least as long as the second.
            limit = (n - i - 1) // 2
            for length in range(1, limit + 1):
                if z[length] >= length:
                    answer += 1
                    # This split was already counted by the first condition.
                    if first_ok and length >= i:
                        answer -= 1

        return answer

