from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        targets = set(targetIndices)
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            old = dp
            dp = old[:]  # retain the character without matching it

            if i in targets:
                for k, value in enumerate(old):
                    if value != neg:
                        dp[k] = max(dp[k], value + 1)

            for k in range(m):
                if ch == pattern[k] and old[k] != neg:
                    dp[k + 1] = max(dp[k + 1], old[k])

        return dp[m]

